-- Read-only projection of this module's tables for the AI analyst (aiquery).

CREATE OR REPLACE VIEW `ai_customers` AS select `crm_customers`.`id` AS `id`,`crm_customers`.`owner_id` AS `owner_id`,`crm_customers`.`first_name` AS `first_name`,`crm_customers`.`last_name` AS `last_name`,`crm_customers`.`email` AS `email`,`crm_customers`.`phone` AS `phone`,`crm_customers`.`city` AS `city`,`crm_customers`.`country` AS `country`,`crm_customers`.`loyalty_points` AS `loyalty_points`,`crm_customers`.`total_spent` AS `total_spent`,`crm_customers`.`visit_count` AS `visit_count`,`crm_customers`.`last_visit_at` AS `last_visit_at`,`crm_customers`.`loyalty_tier` AS `loyalty_tier`,`crm_customers`.`is_active` AS `is_active`,`crm_customers`.`created_at` AS `created_at`,`crm_customers`.`updated_at` AS `updated_at` from `crm_customers`;
